package com.modelrag.server.handler;
import com.modelrag.common.dto.ApiResponse; import com.modelrag.common.exception.ErrorCode; import com.modelrag.common.exception.ModelRagException; import org.slf4j.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class GlobalExceptionHandler {private static final Logger log=LoggerFactory.getLogger(GlobalExceptionHandler.class);@ExceptionHandler(ModelRagException.class)ResponseEntity<ApiResponse<Void>> domain(ModelRagException e){HttpStatus status=e.errorCode()==ErrorCode.RATE_LIMITED?HttpStatus.TOO_MANY_REQUESTS:e.errorCode()==ErrorCode.FORBIDDEN?HttpStatus.FORBIDDEN:HttpStatus.BAD_REQUEST;return ResponseEntity.status(status).body(ApiResponse.fail(e.errorCode().code,e.getMessage()));}@ExceptionHandler(IllegalArgumentException.class)@ResponseStatus(HttpStatus.BAD_REQUEST)ApiResponse<Void> validation(IllegalArgumentException e){return ApiResponse.fail(40001,e.getMessage());}@ExceptionHandler(Exception.class)@ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)ApiResponse<Void> other(Exception e){log.error("Unhandled request error",e);return ApiResponse.fail(50000,"内部错误");}}
